/// <summary>
/// PaffH 01.09.25
/// </summary>
/// <param name = "_part">init</param>
/// <param name = "_asValue">boolean</param>
/// <returns>str</returns>
public str filterFromContactPersonEmail(int _part = 0, boolean _asValue = true)
{
    str retValue = '';
    container con;
    switch (_part)
    {
        case 0:
            retValue = this.parmContactPersonEmail();
            break;
        case 1:
            con = str2con(this.parmContactPersonEmail(), '@');
            if (conLen(con) > 0)
            {
                retValue = strFmt(NDXPlaceholderConstants::StarPlaceHolderStar, conPeek(con,1));
            }
            break;
        case 2:
            con = str2con(this.parmContactPersonEmail(), '@');
            if (conLen(con) > 0)
            {
                retValue = conPeek(con,1);
                con = str2con(retValue, '.');
                if (conLen(con) > 1)
                {
                    retValue = strFmt(NDXPlaceholderConstants::StarPlaceHolderStar, conPeek(con,2));
                }
            }
            break;
    }
    if (!_asValue)
    {
        retValue = strFmt('Filter [%1]', retValue);
    }
    return retValue;
}

